import React, { useEffect } from "react";
import { createPortal } from "react-dom";
import { Link } from "react-router-dom";
import { FaUser, FaHospital, FaTimes } from "react-icons/fa";
import "./RegisterModal.css";

const RegisterModal = ({ isOpen, onClose }) => {
  // Prevent body scroll when modal is open
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "unset";
    }
    return () => {
      document.body.style.overflow = "unset";
    };
  }, [isOpen]);

  // Handle escape key
  useEffect(() => {
    const handleEscape = (e) => {
      if (e.key === "Escape" && isOpen) {
        onClose();
      }
    };
    document.addEventListener("keydown", handleEscape);
    return () => document.removeEventListener("keydown", handleEscape);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  const modalContent = (
    <div className="registration-modal-overlay" onClick={onClose}>
      <div
        className="registration-modal"
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
      >
        <button
          className="registration-modal__close"
          onClick={onClose}
          aria-label="Close modal"
        >
          <FaTimes />
        </button>

        <div className="registration-modal__header">
          <h2 className="registration-modal__title">Join Us Today</h2>
          <p className="registration-modal__subtitle">
            Choose your registration type to get started
          </p>
        </div>

        <div className="registration-modal__options">
          <Link
            to="/user-register"
            className="registration-modal__card"
            onClick={onClose}
          >
            <div className="registration-modal__card-icon registration-modal__card-icon--user">
              <FaUser />
            </div>
            <div className="registration-modal__card-content">
              <h3 className="registration-modal__card-title">Candidate Registration</h3>
              <p className="registration-modal__card-description">
                Book appointments, track history, and manage your health profile.
              </p>
              <span className="registration-modal__card-btn">Register as Patient</span>
            </div>
          </Link>

          <Link
            to="/centre-register"
            className="registration-modal__card"
            onClick={onClose}
          >
            <div className="registration-modal__card-icon registration-modal__card-icon--centre">
              <FaHospital />
            </div>
            <div className="registration-modal__card-content">
              <h3 className="registration-modal__card-title">Healthcare Centre</h3>
              <p className="registration-modal__card-description">
                List your services, manage bookings, and reach more patients.
              </p>
              <span className="registration-modal__card-btn">Register as Centre</span>
            </div>
          </Link>
        </div>
      </div>
    </div>
  );

  return typeof document !== "undefined"
    ? createPortal(modalContent, document.body)
    : modalContent;
};

export default RegisterModal;
